  'method1-step3' => 'Սեղմեք Sign կոճակը գործիքագոտում, որը հայտնվում է:',
  'method1-step4' => 'Ընտրեք՝ մուտքագրել ձեր անունը, նկարել ձեր ստորագրությունը մկնիկի կամ սենսորային էկրանով կամ վերբեռնել ձեր ձեռագիր ստորագրության պատկերը:',
  'method1-step5' => 'Կտտացրեք այնտեղ, որտեղ ցանկանում եք տեղադրել ստորագրությունը փաստաթղթի վրա:',
