  'method1-note' => 'Սա ստեղծում է էլեկտրոնային ստորագրություն, որը ներդրված է PDF-ում: Փաստաթուղթը սովորաբար կբացվի ցանկացած ստացողի համար՝ չպահանջելով, որ նրանք ունենան հատուկ հավելված: Ստորագրությունը տեսանելի է և մշտական, թեև այն չի կրում գաղտնագրային ստուգում:',
  'method2-heading' => 'Մեթոդ 2. DocuSign (Արդյունաբերության ստանդարտ բիզնեսի համար)',
  'method2-intro' => 'DocuSign-ը էլեկտրոնային ստորագրության ամենաընդունված ծառայությունն է բիզնես միջավայրերում, մասնավորապես ԱՄՆ-ում, Մեծ Բրիտանիայում և ԵՄ-ում: Դրա անվճար անձնական պլանը թույլ է տալիս ամսական երեք ստորագրության հարցում, ինչը բավարար է երբեմն օգտագործելու համար:',
  'method2-step1' => 'Ստեղծեք անվճար հաշիվ docusign.com կայքում:',
  'method2-step2' => 'Վերբեռնեք ձեր PDF-ը ձեր սարքից, Google Drive-ից կամ Dropbox-ից:',
  'method2-step3' => 'Փաստաթղթին ավելացրեք ստորագրության դաշտեր՝ դրանք քաշելով ճիշտ վայրեր:',
  'method2-step4' => 'Եթե ​​ուրիշները պետք է ստորագրեն, ավելացրեք նրանց էլ. հասցեները որպես հասցեատերեր:',
  'method2-step5' => 'Ավարտեք ստորագրման գործընթացը՝ սեղմելով ձեր ստորագրության դաշտը, ընտրելով ձեր ստորագրության ոճը և կիրառելով այն:',
  'method2-step6' => 'Ներբեռնեք ստորագրված փաստաթուղթը. Այն ներառում է ավարտական ​​վկայական՝ աուդիտի հետքով, որը ցույց է տալիս, թե ով է ստորագրել, երբ և ինչ IP հասցեից:',
  'method2-note' => 'Աուդիտի հետքը հատկապես արժեքավոր է իրավական առումով զգայուն փաստաթղթերի համար: Եթե ​​ստորագրությունը երբևէ վիճարկվում է, DocuSign Ավարտման վկայականը տրամադրում է ժամանակի դրոշմակնիք, թե ով և երբ է ստորագրել փաստաթուղթը:',
  'method3-heading' => 'Մեթոդ 3. iPhone և iPad (ներկառուցված, հավելվածի կարիք չկա)',
  'method3-intro' => 'iOS-ը և iPadOS-ն ունեն բնօրինակ PDF ստորագրում, որը ներկառուցված է Files հավելվածում և Mail հավելվածում՝ առանց երրորդ կողմի գործիքների պահանջի:',
  'method3-step1' => 'Բացեք PDF-ը Ֆայլեր հավելվածում կամ հպեք և պահեք հավելվածը Mail-ում և ընտրեք Նշում:',
  'method3-step2' => 'Հպեք մատիտի պատկերակին՝ «Markup» գործիքագոտին բացելու համար:',
  'method3-step3' => 'Կտտացրեք ներքևի աջում գտնվող գումարած կոճակին և ընտրեք Ստորագրություն:',
  'method3-step4' => 'Նկարեք ձեր ստորագրությունը ձեր մատով կամ Apple Pencil-ով: Դուք կարող եք պահպանել այն հետագա օգտագործման համար:',
  'method3-step5' => 'Քաշեք ստորագրությունը ճիշտ դիրքի վրա և ըստ անհրաժեշտության չափափոխեք այն:',
  'method3-step6' => 'Հպեք Կատարված՝ ստորագրված PDF-ը պահպանելու համար:',
  'method3-note' => 'Այս մեթոդը մշակում է ձեր սարքի ամեն ինչ: Ոչինչ չի վերբեռնվում որևէ սերվերի վրա, ինչը այն դարձնում է լավ պիտանի գաղտնի փաստաթղթերի համար, որոնք դուք չեք ցանկանում ուղարկել ամպային ծառայությանը:',
  'method4-heading' => 'Մեթոդ 4. Android սարքեր',
  'method4-para1' => 'Android-ը չունի ունիվերսալ ներկառուցված PDF ստորագրման գործիք, սակայն Adobe Acrobat Reader-ը Android-ի համար անվճար է և ապահովում է նույն Fill and Sign գործառույթը, որը նկարագրված է Մեթոդ 1-ում: Adobe Fill և Sign հավելվածը հասանելի է նաև առանձին և օպտիմիզացված է հատուկ բջջային ձևի լրացման համար:',
  'method4-para2' => 'Samsung-ի սարքերի օգտագործողների համար Samsung Notes-ը և Samsung Internet-ը երկուսն էլ ներառում են ծանոթագրության գործիքներ, որոնք կարող են օգտագործվել PDF էջում ստորագրություն տեղադրելու համար, թեև աշխատանքային հոսքը ավելի քիչ պարզեցված է, քան Acrobat Reader-ը:',
  'method5-heading' => 'Մեթոդ 5. Mac-ն օգտագործելով նախադիտումը (ամբողջովին անվճար, առանց վերբեռնման)',
  'method5-intro' => 'macOS Preview-ն ունի ստորագրության առանձնահատկություն, որը ցանկացած հարթակում հասանելի անվճար ստորագրման ամենահարմար տարբերակներից մեկն է:',
  'method5-step1' => 'Բացեք PDF-ը նախադիտման մեջ:',
  'method5-step2' => 'Սեղմեք «Markup Toolbar» կոճակը (մատիտի պատկերակը վերևի աջ կողմում):',
  'method5-step3' => 'Կտտացրեք «Ստորագրություն» կոճակը նշագրման գործիքագոտում:',
  'method5-step4' => 'Դուք կարող եք ստորագրություն ստեղծել՝ օգտագործելով ձեր Mac-ի տեսախցիկը, ստորագրված թղթի կտոր պահելով տեսախցիկի վրա կամ նկարելով թրեքփադում:',
  'method5-step5' => 'Ստեղծվելուց հետո սեղմեք պահպանված ստորագրությունը՝ այն փաստաթղթում տեղադրելու համար:',
  'method5-step6' => 'Քաշեք այն ճիշտ դիրքի վրա և պահեք ֆայլը:',
  'method5-note' => 'Նախադիտումը պահպանում է ձեր ստորագրությունը՝ կրկնակի օգտագործման համար, ինչն էլ ավելի արագ է դարձնում հետագա ստորագրումները: Ինչպես iOS մեթոդը, ամեն ինչ մնում է ձեր սարքում:',
  'cannot-sign-heading' => 'Որ փաստաթղթերը չեն կարող թվային ստորագրվել',
  'cannot-sign-para1' => 'Էլեկտրոնային ստորագրությունները վավեր չեն բոլոր տեսակի փաստաթղթերի համար: Հետևյալ կատեգորիաները սովորաբար պահանջում են վկա ձեռքով գրված ստորագրություններ, նոտարական վավերացում կամ հատուկ պաշտոնական ընթացակարգեր. կտակներ և կտակներ, որդեգրման փաստաթղթեր, որոշ իրավասություններում գույքի փոխանցման փաստաթղթեր, դատական ​​կարգադրություններ և սակարկելի փաստաթղթեր, ինչպիսիք են չեկերը և մուրհակները:',
  'cannot-sign-para2' => 'Եթե ​​վստահ չեք, թե արդյոք էլեկտրոնային ստորագրությունը իրավաբանորեն վավեր է ձեր իրավասության որոշակի փաստաթղթի համար, նախքան դրա վրա հիմնվելը ստացեք իրավաբանական խորհրդատվություն: Սա հատկապես կարևոր է միջազգային պայմանագրերի համար, որտեղ մի քանի երկրների օրենքներ կարող են կիրառվել միաժամանակ:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-para1' => 'Թվային PDF ստորագրումը հասուն է, օրինական և անվճար հասանելի յուրաքանչյուր հիմնական սարքի վրա: Առօրյա բիզնես փաստաթղթերի համար Adobe Acrobat Reader\'s Fill and Sign ֆունկցիան կամ ձեր սարքի ներկառուցված գործիքները կատարում են աշխատանքը երկու րոպեից պակաս ժամանակում: Բարձրարժեք պայմանագրերի կամ փաստաթղթերի համար, որոնք աուդիտի հետքի կարիք ունեն, DocuSign-ը և Adobe Sign-ը ապահովում են լրացուցիչ անվտանգություն և փաստաթղթեր, որոնք պահանջում են այդ իրավիճակները:',
  'conclusion-para2' => 'Եթե ​​Ձեզ անհրաժեշտ է ստորագրման համար PDF պատրաստել՝ ավելացնելով ձևի դաշտերը, տես ուղեցույցը, թե ինչպես կատարել PDF-ը լրացվող: Ստորագրված PDF-ն ուղարկելուց առաջ սեղմելու համար օգտագործեք PDFTools-ի անվճար սեղմման գործիքը:',
  'faqs-heading' => 'Հաճախակի տրվող հարցեր',
  'faq1-question' => 'Արդյո՞ք թվային ստորագրությունները իրավաբանորեն պարտադիր են:',
  'faq1-answer' => 'Շատ երկրներում՝ այո։ ԵՄ eIDAS կանոնակարգը, ԱՄՆ ESIGN ակտը և UETA-ն, Միացյալ Թագավորության Էլեկտրոնային հաղորդակցության ակտը և իրավասությունների մեծ մասի համարժեք օրենսդրությունը էլեկտրոնային ստորագրություններին օրինական ուժ են տալիս առևտրային համաձայնագրերի մեծ մասի համար: Հիմնական պահանջը ստորագրելու մտադրության ապացույցն է, որը բավարարում են վերը նկարագրված բոլոր մեթոդները:',
  'faq2-question' => 'Ի՞նչ կլինի, եթե փաստաթուղթը ստորագրելուց հետո փոփոխվի:',
  'faq2-answer' => 'Որպես պատկեր տեղադրված պարզ էլեկտրոնային ստորագրությամբ փաստաթուղթը կարող է փոփոխվել առանց հայտնաբերման: DocuSign-ի կամ Adobe Sign-ի նման ծառայությունների գաղտնագրային թվային ստորագրությամբ ցանկացած փոփոխություն անհապաղ անվավեր է դարձնում ստորագրությունը, իսկ PDF ընթերցողները ցուցադրում են նախազգուշացում: Փաստաթղթերի համար, որտեղ ամբողջականությունը կարևոր է, օգտագործեք ծառայություն, որն ապահովում է գաղտնագրման ստորագրում:',
  'faq3-question' => 'Կարո՞ղ եմ ստորագրել գաղտնաբառով պաշտպանված PDF-ը:',
  'faq3-answer' => 'Ընդհանրապես ոչ, ոչ առանց նախապես ճիշտ գաղտնաբառը մուտքագրելու: Փաստաթուղթն իր գաղտնաբառով ապակողպելուց հետո կարող եք շարունակել ստորագրումը: Որոշ պաշտպանված PDF-ներ ունեն թույլտվություններ, որոնք սահմանափակում են ստորագրումը նույնիսկ գաղտնաբառի մուտքագրումից հետո, որի դեպքում անհրաժեշտ է, որ փաստաթուղթը ստեղծողը տրամադրի ապակողպված տարբերակը:',
  'faq4-question' => 'Ինչպե՞ս կարող եմ պահանջել, որ մեկ ուրիշը ստորագրի PDF-ը:',
  'faq4-answer' => 'Ծառայությունները, ինչպիսիք են DocuSign-ը, Adobe Sign-ը և Dropbox Sign-ը, թույլ են տալիս վերբեռնել PDF, նշել, թե որտեղ պետք է ստորագրի յուրաքանչյուր անձ և ստորագրման հարցումներ ուղարկել էլ. Յուրաքանչյուր ստացող կտտացնում է հղումը, ստորագրում է էլեկտրոնային եղանակով, և բոլոր կողմերն ավտոմատ կերպով ստանում են ավարտված փաստաթուղթը, երբ բոլորը ստորագրում են:',
  'a'=>'<a href="' . localized_route('compress-pdf') . '">ստորագրված PDF-ի սեղմում</a>',
  'b' => 'ուղարկելուց առաջ օգտագործեք անվճար սեղմման գործիք PDFTools-ում:',
);
